export const shareVestingDefinitions={
  shareVesting:{title:'Separate an award’s units, vesting percentage and gross notional value',fields:[
    ['awardUnits','Units in one hypothetical share-linked award',600,0,100000,100],
    ['awardPrice','Independent CAD share-price assumption for the comparison',50,0,500,5],
    ['completedVestingYears','Completed service years at the comparison date',2,0,10,1],
    ['awardCliffYears','Cliff schedule: full vesting after this many whole years',3,1,10,1],
    ['awardGradualYears','Gradual schedule: equal annual portions over this many years',5,1,10,1]
  ]}
};
export function shareAwardValue(input,years=input.completedVestingYears,mode='gradual',gradualYears=input.awardGradualYears){
  if(!['cliff','gradual'].includes(mode))throw Error('Unknown vesting schedule.');
  const fraction=mode==='cliff'?(years>=input.awardCliffYears?1:0):Math.min(1,years/gradualYears);
  const vestedUnits=input.awardUnits*fraction,unvestedUnits=input.awardUnits-vestedUnits,total=input.awardUnits*input.awardPrice;
  return {fraction,vestedUnits,unvestedUnits,total,vested:vestedUnits*input.awardPrice,unvested:unvestedUnits*input.awardPrice};
}
export function shareVestingResult(kind,input){
  if(kind!=='shareVesting')throw Error('Unknown share-vesting topic.');
  const cliff=shareAwardValue(input,input.completedVestingYears,'cliff'),gradual=shareAwardValue(input);
  return {metrics:[['Whole award at the entered price · gross notional value',gradual.total,'money'],['Cliff schedule · gross value of vested units',cliff.vested,'money'],['Gradual schedule · gross value of vested units',gradual.vested,'money']],note:'One original hypothetical share-linked award, with alternative service-only vesting schedules applied to the same units. “Cliff” means none until the selected whole-year milestone, then all; “gradual” means equal portions after each completed year until full vesting. No partial-year service, monthly vesting, performance hurdles, new grants, dividends, acceleration, replacement awards or actual plan terms are included. A single independent CAD share-price assumption values all units and scenarios; it is not a price quote, stock forecast, accounting grant-date fair value or guaranteed payment. No shares are sold and no cash is credited. All amounts are gross, before tax, withholding and dealing costs. Vesting does not establish delivery timing, permission to sell or spendable proceeds. Fractional units are retained mathematically; actual award rounding is not modeled.',charts:[
    {id:'share-vesting-schedules',type:'line',title:'The two service rules can give different vested percentages at the same date',unit:'percent',unitLabel:'Cumulative vested share of one original award',xLabel:'Completed service years',series:[['Cliff schedule','cliff'],['Equal annual portions','gradual']].map(([name,mode],i)=>({name,step:true,dash:i===1,rows:Array.from({length:11},(_,x)=>({x,value:shareAwardValue(input,x,mode).fraction}))})),note:'Vesting changes only after completed whole service years in these stated rules. The price and number of units do not affect the percentages. The cliff curve jumps once; the gradual curve rises by equal annual fractions. Curves coincide when their rules produce the same percentage. Neither schedule is presented as a legal minimum or a standard employer contract.'},
    {id:'share-vesting-composition',type:'stackbar',title:'The same whole-award value can contain different vested and unvested portions',unit:'money',seriesNames:['Gross value of vested units','Gross value of units not yet vested'],rows:[{label:'Cliff · year '+input.completedVestingYears,values:[cliff.vested,cliff.unvested]},{label:'Gradual · year '+input.completedVestingYears,values:[gradual.vested,gradual.unvested]}],note:'Both bars use the same original units and entered price. Their totals therefore match, while the vesting classification can differ. A notional value on an award screen is not a deposit balance. No part of the unvested segment is treated as money already available, and the vested segment is not converted into after-tax cash.'},
    {id:'share-vesting-gross-bridge',type:'waterfall',title:'For the gradual schedule, remove the unvested portion once',unit:'money',rows:[{label:'Whole-award gross notional value',value:gradual.total},{label:'Gross value attached to unvested units',value:-gradual.unvested}],totalLabel:'Gross value of vested units',note:'This is a classification bridge, not a payment ledger. It reconciles whole-award value minus the unvested portion to the vested portion under the gradual rule. The negative step is not a cash penalty or a trading loss already realized. Actual treatment on departure must come from the award documents and applicable terms.'},
    {id:'share-vesting-gradual-matrix',type:'heatmap',title:'Unvested gross value changes with the date and the gradual vesting period',unit:'money',columns:['2 yr','3 yr','5 yr','7 yr'],rows:[1,2,3,5].map(years=>({label:'Year '+years,values:[2,3,5,7].map(gradualYears=>shareAwardValue(input,years,'gradual',gradualYears).unvested)})),note:'Rows replace completed service years; columns replace the period over which equal annual portions fully vest. Cells value the remaining unvested units at the same entered price. The selected cliff milestone does not enter this gradual-only grid. Zero means no units remain unvested under that mathematical schedule, not guaranteed delivery, a permitted sale or sufficient cash for a goal. Dates and schedules have no assigned probabilities.'}
  ]};
}
